INSERT INTO "Book" ("id","slug","title","author","editora","editoraId","categoryId","coverUrl","countryOrigin","allowQuote","schoolGrade","subject","educationLevel","updatedAt")
SELECT 'novas_capas_' || c.slug,c.slug,c.title,c.author,c.editora,e."id",cat."id",c.cover,'Moçambique',true,c.grade,c.subject,c.level::"EducationLevel",CURRENT_TIMESTAMP
FROM capas c JOIN "Editora" e ON e."name" = c.editora JOIN "Category" cat ON cat."name" = c.category
ON CONFLICT ("slug") DO NOTHING;
