UPDATE "Book" b SET "coverUrl" = c.cover, "updatedAt" = CURRENT_TIMESTAMP FROM capas c
WHERE b."slug" = c.slug AND lower(trim(b."editora")) = lower(c.editora);
UPDATE "Book" SET "coverUrl" = '/covers/' || "slug" || '.jpg', "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" IN ('educacao-visual-e-oficios-6a-classe','o-mundo-da-matematica-1a-classe') AND lower(trim("editora")) = 'alcance editores';
